1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     This module describes a configurable number of flip-flops in the synchronisation chain.
4	--! @details:   This module is a wrapper for the Xilinx XPM CDC block.
5	--! @details:   Thus, it won't work with other synthesis tools.
6	--!
7	--! @license This project is released under the terms of the MIT License. See LICENSE for more details.
8	--!
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	
13	entity ff_synchroniser_vector is
14	    generic (
15	        DEST_SYNC_FF: positive range 2 to 10 := 4;
16	        SIM_INIT_SYNC_FF: boolean := false;     --! false=disable simulation init values, true=enable simulation init values
17	        SIM_ASSERT_CHK: boolean := false;   --! false=disable simulation messages, true=enable simulation messages
18	        SRC_INPUT_REG: boolean := true      --! false=do not register input, true=register input (to catch combinatorial logic)
19	    );
20	    port (
21	        source_clk: in std_ulogic;
22	        destination_clk: in std_ulogic;
23	
24	        in_data: in std_ulogic_vector;
25	        in_data_valid: in std_ulogic;
26	        out_data: out std_ulogic_vector;
27	        out_data_valid: out std_ulogic
28	    );
29	end entity;
30	
31	Library xpm;
32	use xpm.vcomponents.all;
33	
34	architecture xilinx_behavioural_ff_synchroniser_vector of ff_synchroniser_vector is
35	    signal sync_chain_out: std_ulogic_vector(in_data'length downto 0); -- +1 for the valid bit
36	begin
37	    out_data_valid <= sync_chain_out(in_data'high + 1);
38	    out_data <= sync_chain_out(out_data'range);
39	
40	    xpm_cdc_array_single_inst: xpm_cdc_array_single
41	        generic map (
42	            DEST_SYNC_FF => DEST_SYNC_FF,
43	            INIT_SYNC_FF => boolean'pos(SIM_INIT_SYNC_FF),
44	            SIM_ASSERT_CHK => boolean'pos(SIM_ASSERT_CHK),
45	            SRC_INPUT_REG => boolean'pos(SRC_INPUT_REG),
46	            WIDTH => sync_chain_out'length
47	        )
48	        port map (
49	            src_clk => source_clk,
50	            dest_clk => destination_clk,
51	            src_in => in_data_valid & in_data,
52	            dest_out => sync_chain_out
53	    );
54	end architecture;
55	
56	--!
57	--! @brief: This module is a generic synchroniser that can be used to cross clock domains.
58	--! @note:  This module is a technology specific synchroniser, however, it can be used technology independent, where the altera_attribute can be ignored.
59	--! @note:  The FFs should be placed together to get a reliable crossing.
60	--! @note:  Use this if you don't have a technology specific synchroniser.
61	--!
62	architecture intel_behavioural_ff_synchroniser_vector of ff_synchroniser_vector is
63	    signal meta_stable_data_reg: in_data'subtype;
64	    signal meta_stable_valid_reg: std_ulogic;
65	
66	    type in_data_arr_t is array (DEST_SYNC_FF - 2 downto 0) of in_data'subtype; -- -2: Including meta_stable_reg
67	    signal sync_chain_data: in_data_arr_t;
68	    signal sync_chain_valid: std_ulogic_vector(in_data_arr_t'range);
69	
70	    signal source_data_registered: in_data'subtype;
71	    signal source_valid_registered: std_ulogic;
72	
73	    attribute altera_attribute: string;
74	    attribute altera_attribute of meta_stable_data_reg: signal is "-name SYNCHRONIZER_IDENTIFICATION ""FORCED IF ASYNCHRONOUS""";
75	    -- Apply a SDC constraint to meta stable flip flop
76	    attribute altera_attribute of intel_behavioural_ff_synchroniser_vector: architecture is "-name SDC_STATEMENT ""set_false_path -to [get_registers {*|sync_chain_in_dst_dom_proc:*|:meta_stable_data_reg}] """;
77	
78	    -- set 'preserve' attribute to src_reg and sync_chain -> the synthesis tool doesn't optimise them away
79	    attribute preserve: boolean;
80	    attribute preserve of meta_stable_data_reg: signal is true;
81	    attribute preserve of meta_stable_valid_reg: signal is true;
82	    attribute preserve of sync_chain_data: signal is true;
83	    attribute preserve of sync_chain_valid: signal is true;
84	begin
85	    -- Catch the incoming signal in the source domain to ensure
86	    -- there are no combinatorial elements before crossing
87	    comb_reg_source_dom_proc: process (source_clk)
88	    begin
89	        if rising_edge(source_clk) then
90	            source_data_registered <= in_data;
91	            source_valid_registered <= in_data_valid;
92	        end if;
93	    end process;
94	
95	    -- N bits sync chain in the sync_chain_ domain
96	    sync_chain_in_dst_dom_proc: process (destination_clk)
97	    begin
98	        if rising_edge(destination_clk) then
99	            meta_stable_data_reg <= source_data_registered;  -- First element of the sync chain
100	            meta_stable_valid_reg <= source_valid_registered;
101	            sync_chain_data <= sync_chain_data(sync_chain_data'high - 1 downto sync_chain_data'low) & meta_stable_data_reg;
102	            sync_chain_valid <= sync_chain_valid(sync_chain_valid'high - 1 downto sync_chain_valid'low) & meta_stable_valid_reg;
103	        end if;
104	    end process;
105	
106	    out_data <= sync_chain_data(sync_chain_data'high);
107	    out_data_valid <= sync_chain_valid(sync_chain_valid'high);
108	end architecture;
