1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     This module is a wrapper for the async FIFO of Xilinx technology.
4	--! @details:   Based on Simulation and Synthesis Techniques for Asynchronous FIFO Design by Clifford E. Cummings, Sunburst Design, Inc.
5	--!
6	--! @license This project is released under the terms of the MIT License. See LICENSE for more details.
7	--!
8	
9	library ieee;
10	use ieee.std_logic_1164.all;
11	use ieee.numeric_std.all;
12	
13	use work.utils_pkg.all;
14	use work.memories_pkg.all;
15	
16	entity fifo_async is
17	    generic (
18	        FIFO_DEPTH_IN_BITS: natural range 0 to to_bits(natural'high) := 2;
19	        CDC_SYNC_STAGES: positive := 2;
20	        INTEL_DEVICE_FAMILY: string := "Cyclone V"; -- Change this to your target Intel device family
21	        INTEL_CLOCKS_ARE_SYNCHRONIZED: boolean := false
22	    );
23	    port (
24	        aclr: in std_ulogic;
25	        write_clk: in std_ulogic;
26	        read_clk: in std_ulogic;
27	        write_enable: in std_ulogic;
28	        write_data: in std_ulogic_vector;
29	        read_enable: in std_ulogic;
30	        read_data: out std_ulogic_vector;
31	        read_data_valid: out std_ulogic;
32	        full: out std_ulogic;
33	        empty: out std_ulogic;
34	        words_stored: out natural range 0 to 2**FIFO_DEPTH_IN_BITS;
35	
36	        -- Reset read pointer for data replay (keeps write pointer intact)
37	        reset_read_pointer: in std_ulogic := '0'
38	    );
39	
40	    constant FIFO_DEPTH: natural := 2**FIFO_DEPTH_IN_BITS;
41	    constant ADDRESS_WIDTH: natural := to_bits(FIFO_DEPTH);
42	end entity;
43	
44	library xpm;
45	use xpm.vcomponents.all;
46	
47	--!
48	--! @brief: This module is a Xilinx technology specific FIFO memory block.
49	--! @note:  This module is a wrapper for the xpm_fifo_async module.
50	--! @note:  Use this primarily for Xilinx technology.
51	--!
52	architecture xilinx_behavioural_async_fifo of fifo_async is
53	    signal prog_full_unconnected: std_ulogic;
54	    signal prog_empty_unconnected: std_ulogic;
55	    signal wr_data_count: std_ulogic_vector(ADDRESS_WIDTH downto 0);
56	    signal rd_data_count_unconnected: std_ulogic_vector(0 downto 0);
57	    signal wr_ack_unconnected: std_ulogic;
58	    signal overflow_unconnected: std_ulogic;
59	    signal underflow_unconnected: std_ulogic;
60	    signal wr_rst_busy_unconnected: std_ulogic;
61	    signal rd_rst_busy_unconnected: std_ulogic;
62	    signal almost_full_unconnected: std_ulogic;
63	    signal almost_empty_unconnected: std_ulogic;
64	    signal sbiterr_unconnected: std_ulogic;
65	    signal dbiterr_unconnected: std_ulogic;
66	begin
67	    words_stored <= to_integer(unsigned(wr_data_count));
68	    xpm_fifo_inst: xpm_fifo_async
69	        generic map (
70	            FIFO_MEMORY_TYPE => "auto",
71	            FIFO_WRITE_DEPTH => FIFO_DEPTH,
72	            CDC_SYNC_STAGES => CDC_SYNC_STAGES,
73	            CASCADE_HEIGHT => 0,
74	            WRITE_DATA_WIDTH => write_data'length,
75	            READ_MODE => "std",
76	            FIFO_READ_LATENCY => 1,
77	            FULL_RESET_VALUE => 0,
78	            USE_ADV_FEATURES => "0707",
79	            READ_DATA_WIDTH => read_data'length,
80	            WR_DATA_COUNT_WIDTH => wr_data_count'length,
81	            PROG_FULL_THRESH => 10,
82	            RD_DATA_COUNT_WIDTH => rd_data_count_unconnected'length,
83	            PROG_EMPTY_THRESH => 10,
84	            DOUT_RESET_VALUE => "0",
85	            ECC_MODE => "no_ecc",
86	            SIM_ASSERT_CHK => 0,
87	            RELATED_CLOCKS => 0,
88	            WAKEUP_TIME => 0
89	        )
90	        port map (
91	            sleep => '0',
92	            rst => aclr,
93	            wr_clk => write_clk,
94	            wr_en => write_enable,
95	            din => write_data,
96	            full => full,
97	            prog_full => prog_full_unconnected,
98	            wr_data_count => wr_data_count,
99	            overflow => overflow_unconnected,
100	            wr_rst_busy => wr_rst_busy_unconnected,
101	            almost_full => almost_full_unconnected,
102	            wr_ack => wr_ack_unconnected,
103	            rd_en => read_enable and not reset_read_pointer,
104	            rd_clk => read_clk,
105	            dout => read_data,
106	            empty => empty,
107	            prog_empty => prog_empty_unconnected,
108	            rd_data_count => rd_data_count_unconnected,
109	            underflow => underflow_unconnected,
110	            rd_rst_busy => rd_rst_busy_unconnected,
111	            almost_empty => almost_empty_unconnected,
112	            data_valid => read_data_valid,
113	            injectsbiterr => '0',
114	            injectdbiterr => '0',
115	            sbiterr => sbiterr_unconnected,
116	            dbiterr => dbiterr_unconnected
117	        );
118	end architecture;
119	
120	library altera_mf;
121	use altera_mf.altera_mf_components.all;
122	
123	architecture intel_behavioural_async_fifo of fifo_async is
124	    function boolean_to_string(b: boolean) return string is begin
125	        if b then
126	            return "TRUE";
127	        else
128	            return "FALSE";
129	        end if;
130	    end function;
131	
132	    signal words_stored_slv: std_ulogic_vector(ADDRESS_WIDTH downto 0);
133	begin
134	    -- NOTE: -- enable_ecc and write_aclr_synch are not supported in the Intel Cyclone V device family.
135	    fifo: dcfifo
136	        generic map (
137	            add_ram_output_register => "OFF",
138	            intended_device_family => INTEL_DEVICE_FAMILY,
139	            lpm_type => "dcfifo",
140	            lpm_hint => "DISABLE_DCFIFO_EMBEDDED_TIMING_CONSTRAINT=TRUE",
141	            lpm_showahead => "OFF",
142	            use_eab => "ON", -- ON = RAM, OFF Register
143	            -- enable_ecc => "FALSE",
144	            ram_block_type => "AUTO",
145	            overflow_checking => "ON",
146	            underflow_checking => "ON",
147	
148	            clocks_are_synchronized => boolean_to_string(INTEL_CLOCKS_ARE_SYNCHRONIZED),
149	            wrsync_delaypipe => 0, -- The values of this parameter is internally reduced by two.
150	            rdsync_delaypipe => 0, -- The values of this parameter is internally reduced by two.
151	            delay_rdusedw => 1,
152	            delay_wrusedw => 1,
153	            write_aclr_synch => "OFF",
154	            -- read_aclr_synch => "OFF",
155	
156	            lpm_numwords => FIFO_DEPTH,
157	            lpm_widthu => to_bits(FIFO_DEPTH),
158	            lpm_width => write_data'length,
159	            add_usedw_msb_bit => "OFF"
160	        )
161	        port map (
162	            aclr => aclr,
163	
164	            wrclk => write_clk,
165	            data => write_data,
166	            wrreq => write_enable,
167	            wrempty => open,
168	            wrfull => full,
169	            wrusedw => words_stored_slv,
170	
171	            rdclk => read_clk,
172	            q => read_data,
173	            rdreq => read_enable,
174	            rdempty => empty,
175	            rdfull => open,
176	            rdusedw => open -- May not be available
177	        );
178	
179	        read_data_valid <= read_enable when rising_edge(read_clk);
180	        words_stored <= to_integer(unsigned(words_stored_slv)) when not full else words_stored'subtype'high;
181	end architecture;
182	
183	--!
184	--! @brief: This module is a generic FIFO memory block.
185	--! @note:  This module is technology independent and can be replaced with a technology specific async FIFO module.
186	--! @note:  Use this if you don't have a technology specific async FIFO.
187	--!
188	architecture own_behavioural_async_fifo of fifo_async is
189	    subtype pointer_t is unsigned(ADDRESS_WIDTH downto 0);
190	
191	    signal write_pointer_binary: pointer_t;
192	    signal read_pointer_binary: pointer_t;
193	
194	    signal write_pointer_gray: std_ulogic_vector(pointer_t'range);
195	    signal read_pointer_gray: std_ulogic_vector(pointer_t'range);
196	
197	    signal write_pointer_gray_sync: std_ulogic_vector(pointer_t'range);
198	    signal read_pointer_gray_sync: std_ulogic_vector(pointer_t'range);
199	
200	    signal write_address: std_ulogic_vector(ADDRESS_WIDTH - 1 downto 0);
201	    signal read_address: std_ulogic_vector(ADDRESS_WIDTH - 1 downto 0);
202	
203	    function binary_to_gray(binary: unsigned) return std_ulogic_vector is begin
204	        return std_ulogic_vector(binary xor ('0' & binary(binary'high downto 1)));
205	    end function;
206	
207	    function gray_to_binary(gray: std_ulogic_vector) return unsigned is
208	        variable binary: unsigned(gray'range);
209	    begin
210	        binary(gray'high) := gray(gray'high);
211	        for i in gray'high - 1 downto 0 loop
212	            binary(i) := binary(i + 1) xor gray(i);
213	        end loop;
214	        return binary;
215	    end function;
216	begin
217	    words_stored_calc: process (read_clk)
218	        variable write_ptr_sync: unsigned(ADDRESS_WIDTH downto 0);
219	        variable diff: integer;
220	    begin
221	        if rising_edge(read_clk) then
222	            write_ptr_sync := gray_to_binary(write_pointer_gray_sync);
223	            diff := to_integer(write_ptr_sync) - to_integer(read_pointer_binary);
224	            words_stored <= words_stored'subtype'high when full else diff;
225	        end if;
226	    end process;
227	
228	    write_pointer_logic: process (aclr, write_clk)
229	    begin
230	        if aclr then
231	            write_pointer_binary <= (others => '0');
232	            write_pointer_gray <= (others => '0');
233	        elsif rising_edge(write_clk) then
234	            if write_enable and not full then
235	                write_pointer_binary <= write_pointer_binary + 1;
236	                write_pointer_gray <= binary_to_gray(write_pointer_binary + 1);
237	            end if;
238	        end if;
239	    end process;
240	
241	    read_pointer_logic: process (aclr, read_clk)
242	    begin
243	        if aclr then
244	            read_pointer_binary <= (others => '0');
245	            read_pointer_gray <= (others => '0');
246	        elsif rising_edge(read_clk) then
247	            if reset_read_pointer then
248	                -- Reset read pointer to replay data (write pointer stays intact)
249	                read_pointer_binary <= (others => '0');
250	                read_pointer_gray <= (others => '0');
251	            elsif read_enable and not empty then
252	                read_pointer_binary <= read_pointer_binary + 1;
253	                read_pointer_gray <= binary_to_gray(read_pointer_binary + 1);
254	            end if;
255	        end if;
256	    end process;
257	
258	    write_pointer_sync: entity work.ff_synchroniser_vector(xilinx_behavioural_ff_synchroniser_vector)
259	        generic map (
260	            DEST_SYNC_FF => CDC_SYNC_STAGES
261	        )
262	        port map (
263	            source_clk => write_clk,
264	            destination_clk => read_clk,
265	            in_data => write_pointer_gray,
266	            in_data_valid => '1',
267	            out_data => write_pointer_gray_sync,
268	            out_data_valid => open
269	        );
270	
271	    read_pointer_sync: entity work.ff_synchroniser_vector(xilinx_behavioural_ff_synchroniser_vector)
272	        generic map (
273	            DEST_SYNC_FF => CDC_SYNC_STAGES
274	        )
275	        port map (
276	            source_clk => read_clk,
277	            destination_clk => write_clk,
278	            in_data => read_pointer_gray,
279	            in_data_valid => '1',
280	            out_data => read_pointer_gray_sync,
281	            out_data_valid => open
282	        );
283	
284	    empty <= '1' when read_pointer_gray = write_pointer_gray_sync else '0';
285	
286	    full_flag_detect: process (all)
287	        variable pointers_msbs_are_different: boolean;
288	        variable addresses_msbs_are_different: boolean;
289	        variable lower_address_parts_are_equal: boolean;
290	    begin
291	        pointers_msbs_are_different := write_pointer_gray(write_pointer_gray'high) /= read_pointer_gray_sync(read_pointer_gray_sync'high);
292	        addresses_msbs_are_different := write_pointer_gray(write_pointer_gray'high - 1) /= read_pointer_gray_sync(read_pointer_gray_sync'high - 1);
293	        lower_address_parts_are_equal := write_pointer_gray(write_pointer_gray'high - 2 downto 0) = read_pointer_gray_sync(read_pointer_gray_sync'high - 2 downto 0);
294	        full <= '1' when pointers_msbs_are_different and addresses_msbs_are_different and lower_address_parts_are_equal else '0';
295	    end process;
296	
297	    write_address <= std_ulogic_vector(write_pointer_binary(write_address'range));
298	    read_address <= std_ulogic_vector(read_pointer_binary(read_address'range));
299	
300	    valid_flag_detect: process (aclr, read_clk)
301	    begin
302	        if aclr then
303	            read_data_valid <= '0';
304	        elsif rising_edge(read_clk) then
305	            read_data_valid <= read_enable and not empty;
306	        end if;
307	    end process;
308	
309	    dual_port_ram_inst: entity work.dual_clock_dual_port_ram
310	        port map (
311	            write_clk => write_clk,
312	            write_enable => write_enable and not full,
313	            write_data => write_data,
314	            write_address => write_address,
315	            read_clk => read_clk,
316	            read_data => read_data,
317	            read_address => read_address
318	        );
319	end architecture;
