1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     Unit tests for the ff_synchroniser module.
4	--! @note:      We only test the own_behavioural_ff_synchroniser architecture,
5	--!             as the xilinx_behavioural_ff_synchroniser is technology dependent, therefore already tested.
6	--!
7	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
8	--!
9	
10	-- vunit: run_all_in_same_sim
11	
12	library ieee;
13	use ieee.std_logic_1164.all;
14	use ieee.numeric_std.all;
15	
16	library vunit_lib;
17	context vunit_lib.vunit_context;
18	
19	library osvvm;
20	use osvvm.RandomPkg.RandomPType;
21	
22	use work.utils_pkg.all;
23	use work.tb_utils.all;
24	
25	
26	entity tb_ff_synchroniser is
27	    generic (
28	        runner_cfg: string := runner_cfg_default;
29	        tb_path: string;
30	        SIMULATION_TIMEOUT_IN_MS: string
31	    );
32	end entity;
33	
34	architecture tb of tb_ff_synchroniser is
35	    -------------------------------------------------------------
36	    -- Internal tb signals/constants
37	    -------------------------------------------------------------
38	    constant MINIMUM_SIMULATION_TIME_IN_MS: real := 3.7; -- Minimum time needed for synchronizer test
39	    constant REQUESTED_SIMULATION_TIMEOUT_TIME: time := real'value(SIMULATION_TIMEOUT_IN_MS) * 1 ms;
40	    constant SIMULATION_TIMEOUT_TIME: time := maximum(REQUESTED_SIMULATION_TIMEOUT_TIME, MINIMUM_SIMULATION_TIME_IN_MS * 1 ms);
41	    constant ENABLE_DEBUG_PRINT: boolean := false;
42	
43	    constant SOURCE_CLK_FREQUENCY: real := real(100e6);
44	    constant DESTINATION_CLK_FREQUENCY: real := real(25e6);
45	    constant SYS_CLK_PHASE: time := 0 fs;
46	
47	    signal source_clk_enable: std_ulogic := '1';
48	    signal destination_clk_enable: std_ulogic := '1';
49	    signal simulation_done: boolean := false;
50	    -------------------------------------------------------------
51	
52	    -------------------------------------------------------------
53	    -- DuT signals, constants
54	    -------------------------------------------------------------
55	    constant SYNC_SHIFT_FF: positive := 4;
56	    constant INIT_SYNC_FF: boolean := false;
57	    constant SIM_ASSERT_MSG: boolean := true;
58	    constant SRC_INPUT_REG: boolean := true;
59	
60	    signal source_clk: std_ulogic := '0';
61	    signal destination_clk: std_ulogic := '0';
62	    signal source_domain: std_ulogic := '0';
63	    signal destination_domain_own: std_ulogic;
64	    -------------------------------------------------------------
65	begin
66	    ------------------------------------------------------------
67	    -- CLOCK and RESET Generation
68	    ------------------------------------------------------------
69	    generate_advanced_clock(source_clk, SOURCE_CLK_FREQUENCY, SYS_CLK_PHASE, source_clk_enable);
70	    generate_advanced_clock(destination_clk, DESTINATION_CLK_FREQUENCY, SYS_CLK_PHASE, destination_clk_enable);
71	    ------------------------------------------------------------
72	
73	    ------------------------------------------------------------
74	    -- Vunit
75	    ------------------------------------------------------------
76	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
77	
78	    main: process begin
79	        test_runner_setup(runner, runner_cfg);
80	        info("Starting tb_ff_synchroniser");
81	
82	        if REQUESTED_SIMULATION_TIMEOUT_TIME < MINIMUM_SIMULATION_TIME_IN_MS * 1 ms then
83	            warning("Simulation timeout (" & SIMULATION_TIMEOUT_IN_MS & " ms) is less than minimum required (" & real'image(MINIMUM_SIMULATION_TIME_IN_MS) & " ms). Using minimum timeout instead.");
84	        end if;
85	
86	        if ENABLE_DEBUG_PRINT then
87	            show(display_handler, debug);
88	        end if;
89	
90	        wait until simulation_done;
91	        info("Simulation done, all tests passed!" & LF);
92	
93	        test_runner_cleanup(runner);
94	        wait;
95	    end process;
96	    ------------------------------------------------------------
97	
98	    ------------------------------------------------------------
99	    -- Checker
100	    ------------------------------------------------------------
101	    checker: process
102	        variable random: RandomPType;
103	
104	        procedure wait_source_clk_cycles(cycles: natural) is begin
105	            for i in 0 to cycles - 1 loop
106	                wait until rising_edge(source_clk);
107	            end loop;
108	        end procedure;
109	
110	        procedure wait_destination_clk_cycles(cycles: natural) is begin
111	            for i in 0 to cycles - 1 loop
112	                wait until rising_edge(destination_clk);
113	            end loop;
114	        end procedure;
115	
116	        procedure check_destination_domain_own(expected: std_ulogic) is begin
117	            check_equal(got => destination_domain_own, expected => expected, msg => "destination_domain_own");
118	        end procedure;
119	
120	        procedure test_own_ff_synchroniser is
121	            variable BOUNCE_TIME: natural;
122	        begin
123	            info("1.x) test_own_ff_synchroniser");
124	
125	            BOUNCE_TIME := random.RandInt(Min => 1, Max => 100);
126	
127	            info("1.1) Let the synchronizer settle to a known state first");
128	            source_domain <= '0';
129	            wait_destination_clk_cycles(SYNC_SHIFT_FF + 1);
130	            check_destination_domain_own(expected => '0');
131	
132	            info("1.2) destination_domain_own should be '1' when source_domain is '1'");
133	            source_domain <= '1';
134	            wait_destination_clk_cycles(SYNC_SHIFT_FF + 1);
135	            check_destination_domain_own(expected => '1');
136	
137	            info("1.3) Test rapid bouncing - should eventually follow the last stable value");
138	            -- Start from known '1' state, then bounce rapidly
139	            for i in 0 to BOUNCE_TIME / 4 - 1 loop
140	                -- Quick bounce: 0->1->0->1
141	                source_domain <= '0';
142	                wait_source_clk_cycles(1);
143	                source_domain <= '1';
144	                wait_source_clk_cycles(1);
145	                source_domain <= '0';
146	                wait_source_clk_cycles(1);
147	                source_domain <= '1';
148	                wait_source_clk_cycles(1);
149	                -- Don't wait for destination clock - this creates real bouncing
150	            end loop;
151	
152	            -- Now settle to '1' and verify it propagates
153	            source_domain <= '1';
154	            wait_destination_clk_cycles(SYNC_SHIFT_FF + 1);
155	            check_destination_domain_own(expected => '1');
156	
157	            info("1.4) destination_domain_own should be '1' when source_domain settles to '1'");
158	            source_domain <= '1';
159	            wait_destination_clk_cycles(SYNC_SHIFT_FF + 1);
160	            check_destination_domain_own(expected => '1');
161	
162	            info("1.5) Test rapid bouncing from high state");
163	            -- Start from known '1' state, then bounce rapidly
164	            for i in 0 to BOUNCE_TIME / 4 - 1 loop
165	                -- Quick bounce: 1->0->1->0
166	                source_domain <= '1';
167	                wait_source_clk_cycles(1);
168	                source_domain <= '0';
169	                wait_source_clk_cycles(1);
170	                source_domain <= '1';
171	                wait_source_clk_cycles(1);
172	                source_domain <= '0';
173	                wait_source_clk_cycles(1);
174	                -- Don't wait for destination clock - this creates real bouncing
175	            end loop;
176	
177	            -- Now settle to '0' and verify it propagates
178	            source_domain <= '0';
179	            wait_destination_clk_cycles(SYNC_SHIFT_FF + 1);
180	            check_destination_domain_own(expected => '0');
181	
182	            info("1.6) destination_domain_own should be '0' when source_domain settles to '0'");
183	            source_domain <= '0';
184	            wait_destination_clk_cycles(SYNC_SHIFT_FF + 1);
185	            check_destination_domain_own(expected => '0');
186	        end procedure;
